CREATE   VIEW [FO].[vwAUS_NZD]
AS
SELECT 
	c.CUSTGROUP
	,ct.ORDERACCOUNT
	, ct.ACCOUNTNUM 
	, ct.TRANSDATE
	, ct.DUEDATE
	, ct.INVOICE
	, ct.VOUCHER
	, ct.AMOUNTMST
	, ct.AMOUNTCUR
	, ct.CURRENCYCODE
--	, ct.DIMENSION
--	, ct.DIMENSION2_
--	, ct.DIMENSION3_
	, ct.POSTINGPROFILE
	, c.ZIPCODE
	, c.COUNTRYREGIONID
	, c.CITY
	, ct.DATAAREAID
	, c.TAXGROUP
	, ct.RICINVOICETYPE
	, CAST(NULL AS NVARCHAR) AS RICRECALCULATION
	, CAST(NULL AS NVARCHAR) AS RICRECALREFERENCE
	, CAST(NULL AS NVARCHAR) AS RICCUSTINTERFACEREF
	, CAST(NULL AS NVARCHAR) AS HITINTSYSTEMID
	, CAST(NULL AS NVARCHAR) AS RICEXTERNALINVOICEREF

FROM [FO].vwCUSTTRANS ct with (nolock)
	INNER JOIN [FO].vwCUSTTABLE c on c.accountnum = ct.accountnum

WHERE ct.DATAAREAID='rcs'
	AND c.COUNTRYREGIONID IN ('nzl','aus')
	AND ct.TRANSDATE BETWEEN DATETIMEFROMPARTS(DATEPART(YEAR, Getdate())-1,01,01,00,00,00,0) and GETDATE()
--	AND (ct.VOUCHER LIKE 'rev%' OR ct.VOUCHER LIKE '%fti' OR ct.VOUCHER LIKE '%chg' OR ct.VOUCHER LIKE '%cr')
